import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.BGlkWkwp.js";const u=JSON.parse('{"title":"Gtile","description":"","frontmatter":{},"headers":[],"relativePath":"components/gtile.md","filePath":"components/gtile.md"}'),i={name:"components/gtile.md"};function r(l,e,n,s,h,c){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="gtile" tabindex="-1">Gtile <a class="header-anchor" href="#gtile" aria-label="Permalink to &quot;Gtile&quot;">​</a></h1><p>Gtile is one tile of a grid of things shown with a picture, such as documents or folders.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it in a <a href="./grid">Grid</a>, one tile per thing; a thing without a picture is a <a href="./list-item">ListItem</a>. The whole tile is pressed: it takes <code>onclick</code> or <code>href</code>, and a <code>label</code> that names it. The picture goes in <code>thumb</code> (a <a href="./thumbnail">Thumbnail</a> with <code>size=&quot;full&quot;</code>), the title and the details in <code>children</code>, and a menu button in <code>actions</code>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>onclick</code></td><td></td><td>Called when the tile is pressed</td></tr><tr><td><code>href</code></td><td></td><td>Makes the tile a link</td></tr><tr><td><code>label</code></td><td></td><td>The name of the tile</td></tr><tr><td><code>sel</code></td><td><code>false</code></td><td>Selected</td></tr><tr><td><code>thumb</code></td><td></td><td>The picture, edge to edge</td></tr><tr><td><code>actions</code></td><td></td><td>Actions at the top right</td></tr><tr><td><code>children</code></td><td>required</td><td>The title and the details</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>A line around it on the panel surface; the picture reaches the edges, and only the body has padding (pad-md). The body is a Stack with gap 0, so a title and a caption are set by their line heights. A pressed element covers the whole tile and shows the raise surface on hover and the focus ring inside; the actions sit above it, gap-sm from the body, and below 24rem over the top right of the picture. Selected is a blue line of two inside. Controls inside are small buttons.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/gtile/" title="Gtile" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/gtile/" target="_blank" rel="noopener">Gtile</a></figcaption></figure>',10)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
